@tailwind base;
@tailwind components;
@tailwind utilities;

/* T-614. Two shared component classes, because "a bordered card" and "a panel
   heading" appear on every screen and repeating fifteen utilities each time is
   how a design drifts out of alignment. Everything else is utilities in place. */
@layer components {
  .panel {
    @apply rounded-xl border border-paper-line bg-paper-card p-4 shadow-card
           dark:border-night-line dark:bg-night-card dark:shadow-none;
  }
  .panel-title {
    @apply text-[0.72rem] font-semibold uppercase tracking-[0.09em]
           text-ink-dim dark:text-night-dim;
  }
  .field-label {
    @apply mb-1 block text-[0.72rem] font-medium uppercase tracking-[0.08em]
           text-ink-dim dark:text-night-dim;
  }
  .control {
    @apply w-full rounded-lg border border-paper-line bg-paper px-3 py-2 text-sm
           text-ink outline-none transition
           focus:border-accent focus:ring-2 focus:ring-accent/25
           disabled:opacity-50
           dark:border-night-line dark:bg-night dark:text-night-fg;
  }
  .btn-primary {
    @apply rounded-lg bg-accent px-4 py-2 text-sm font-semibold text-white
           transition hover:bg-accent-hover
           disabled:cursor-not-allowed disabled:opacity-45;
  }
  .btn-ghost {
    @apply rounded-md border border-paper-line px-2.5 py-1 text-xs font-medium
           text-ink-dim transition hover:border-accent hover:text-accent
           dark:border-night-line dark:text-night-dim;
  }
}

html { scroll-behavior: smooth; }

body {
  @apply bg-paper text-ink antialiased dark:bg-night dark:text-night-fg;
  font-family: theme('fontFamily.sans');
}

/* Scrollbars inside panels, so a long list does not draw a heavy grey bar
   across a light card. */
.scroll-soft { scrollbar-width: thin; scrollbar-color: theme('colors.paper.line') transparent; }
.scroll-soft::-webkit-scrollbar { width: 8px; height: 8px; }
.scroll-soft::-webkit-scrollbar-thumb {
  background: theme('colors.paper.line'); border-radius: 999px;
}
@media (prefers-color-scheme: dark) {
  .scroll-soft { scrollbar-color: theme('colors.night.line') transparent; }
  .scroll-soft::-webkit-scrollbar-thumb { background: theme('colors.night.line'); }
}
===== src/api.js =====
// Thin wrapper over the five endpoints in PROJECT_PLAN §7.2.
//
// No store (TASKLIST T-604: "no Pinia - one page, one run, a store is
// ceremony"). State lives in App.vue; this file only talks to the network.

async function json(path, options) {
  const res = await fetch(path, options)
  if (!res.ok) {
    let detail = `${res.status} ${res.statusText}`
    try {
      const body = await res.json()
      if (body.detail) detail = body.detail
    } catch {
      /* a non-JSON error body is fine; keep the status line */
    }
    throw new Error(detail)
  }
  return res.json()
}

export const health = () => json('/api/health')
export const listRuns = () => json('/api/runs?limit=50')
export const getResult = (runId) => json(`/api/runs/${encodeURIComponent(runId)}/result`)

export const startReview = (question, maxPapers) =>
  json('/api/review', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ question, max_papers: maxPapers, use_loop: true }),
  })

// T-609. Persisted to the run's trace, so an override survives a reload.
export const postOverride = (runId, claimId, decision, note) =>
  json(`/api/runs/${encodeURIComponent(runId)}/overrides`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ claim_id: claimId, decision, note }),
  })

// T-612. The sheet is rebuilt from the run's trace on every request, so it
// survives an API restart and shows what a previous session already scored.
export const getScoreSheet = (runId) =>
  json(`/api/runs/${encodeURIComponent(runId)}/scores`)

export const postScores = (runId, body) =>
  json(`/api/runs/${encodeURIComponent(runId)}/scores`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })

export const artifactUrl = (runId, name) =>
  `/api/runs/${encodeURIComponent(runId)}/artifact/${encodeURIComponent(name)}`

/**
 * Subscribe to a run's trace.
 *
 * The server replays history before following the tail, so a late subscriber
 * still sees the whole story - which is also how a finished run replays for the
 * T-610 demo. `onEvent` therefore receives past events immediately.
 *
 * Returns a close function. Callers MUST call it: an EventSource left open
 * keeps reconnecting after the stream ends and quietly re-runs onEvent.
 */
export function streamEvents(runId, onEvent, onDone) {
  const es = new EventSource(`/api/runs/${encodeURIComponent(runId)}/events`)

  // Named events, because the server sets `event:` to the trace's own event
  // name rather than using a single generic channel.
  es.onmessage = (m) => safeParse(m.data, onEvent)
  for (const name of [
    'run_start', 'agent_start', 'agent_end', 'critic_decision',
    'claims_decomposed', 'verification_summary', 'claim_dropped',
    'extract_progress', 'retrieval_summary', 'rank_summary', 'replanning',
    'run_end', 'run_failed',
  ]) {
    es.addEventListener(name, (m) => safeParse(m.data, onEvent))
  }

  es.addEventListener('done', (m) => {
    safeParse(m.data, (d) => onDone && onDone(d))
    es.close()
  })

  // An error after the server closed a finished stream is normal, not a fault.
  es.onerror = () => es.close()

  return () => es.close()
}

function safeParse(raw, fn) {
  try {
    fn(JSON.parse(raw))
  } catch {
    /* a malformed frame must not kill the stream */
  }
}

