    {
      key: 'planner',
      label: 'Plan',
      value: d.plan ? `${d.plan.subQuestions ?? '—'} sub-questions` : null,
      detail: d.plan
        ? `${d.plan.searchTasks ?? '—'} search tasks · facets: ${
            (d.plan.facets || []).join(', ') || 'none'}`
        : 'not started',
    },
    {
      key: 'retriever',
      label: 'Retrieve',
      value: d.retrieval ? `${n(d.retrieval.newPapers)} papers` : null,
      detail: d.retrieval
