// TEMPORARY verification harness — not part of the app, deleted after the run.
// Renders every panel against the REAL fixture run so a template that throws on
// live data fails here rather than in front of an examiner.
import fs from 'node:fs'
import { createSSRApp, h } from 'vue'
import { renderToString } from 'vue/server-renderer'

import PanelOverview from './src/components/PanelOverview.vue'
import PanelProgress from './src/components/PanelProgress.vue'
import PanelEvidence from './src/components/PanelEvidence.vue'
import PanelDropped from './src/components/PanelDropped.vue'
import PanelSources from './src/components/PanelSources.vue'
import PanelRun from './src/components/PanelRun.vue'
import PanelScores from './src/components/PanelScores.vue'
import AppHeader from './src/components/AppHeader.vue'
import DashboardView from './src/components/DashboardView.vue'
import { digest } from './src/lib/runStats.js'

const RUN = '../outputs/runs/fixture'
const claims = JSON.parse(fs.readFileSync(`${RUN}/claims.json`, 'utf8'))
const corpus = JSON.parse(fs.readFileSync(`${RUN}/corpus.json`, 'utf8'))
const review = fs.readFileSync(`${RUN}/review.md`, 'utf8')
const events = fs.readFileSync(`${RUN}/trace.jsonl`, 'utf8')
  .split('\n').filter(Boolean).map((l) => JSON.parse(l))

const d = digest(events)
const result = {
  run_id: 'fixture',
  status: 'complete',
  question: d.question,
  grounding_score: claims.grounding_score,
  counts: claims.counts,
  verified_claims: claims.verified,
  dropped_claims: claims.dropped,
  papers: corpus.papers.slice(0, 200),
  artefacts: ['review.md', 'claims.json', 'trace.jsonl', 'refs.bib'],
  decisions: ['RETRIEVE', 'REPLAN', 'RETRIEVE', 'WRITE'],
}

const runs = [{
  run_id: '20260828T101500Z-ab12cd34', status: 'complete',
  question: d.question, started: new Date().toISOString(),
  papers: 551, verified_claims: 19, dropped_claims: 3, grounding_score: 0.8636,
}]

// Each case is rendered twice: with the fixture, and with everything empty —
// the state the page is in for the first second of every visit.
const CASES = [
  ['AppHeader', AppHeader, { route: '/', busy: true, fixtureMode: true }],
  ['DashboardView', DashboardView, {}],
  ['PanelRun (loaded)', PanelRun, { runs, busy: false, fixtureMode: true, openRunId: runs[0].run_id }],
  ['PanelRun (empty)', PanelRun, {}],
  ['PanelOverview (loaded)', PanelOverview, { runId: 'fixture', result, digest: d }],
  ['PanelOverview (empty)', PanelOverview, { runId: '', result: null, digest: digest([]) }],
  ['PanelProgress (loaded)', PanelProgress, { digest: d, running: true }],
  ['PanelProgress (empty)', PanelProgress, { digest: digest([]) }],
  ['PanelEvidence (loaded)', PanelEvidence, {
    reviewMarkdown: review, verifiedClaims: claims.verified, papers: result.papers }],
  ['PanelEvidence (empty)', PanelEvidence, {}],
  ['PanelDropped (loaded)', PanelDropped, {
    runId: 'fixture', droppedClaims: claims.dropped, verifiedCount: 19,
    artefacts: result.artefacts, overrides: { c0006: 'reinstate' },
    overrideNotes: { c0006: 'the abstract does say this' },
    threshold: d.verify.threshold }],
  ['PanelDropped (empty)', PanelDropped, {}],
  ['PanelSources (loaded)', PanelSources, {
    papers: result.papers, verifiedClaims: claims.verified,
    droppedClaims: claims.dropped, extractedIds: corpus.extracted_paper_ids,
    corpusTotal: 551 }],
  ['PanelSources (empty)', PanelSources, {}],
  ['PanelScores (no run)', PanelScores, { runId: '' }],
]

let failures = 0
for (const [name, component, props] of CASES) {
  try {
    const app = createSSRApp({ render: () => h(component, props) })
    app.config.warnHandler = (msg) => { throw new Error(`vue warning: ${msg}`) }
    const html = await renderToString(app)
    console.log(`  ok   ${name.padEnd(26)} ${String(html.length).padStart(7)} chars`)
  } catch (e) {
    failures += 1
    console.log(`  FAIL ${name}\n       ${e.message}`)
  }
}

// Spot-check that the new panels actually put the derived facts on the page,
// rather than rendering an empty shell without error.
const overview = await renderToString(
  createSSRApp({ render: () => h(PanelOverview, { runId: 'fixture', result, digest: d }) }))
const sources = await renderToString(
  createSSRApp({ render: () => h(PanelSources, {
    papers: result.papers, verifiedClaims: claims.verified,
    droppedClaims: claims.dropped, extractedIds: corpus.extracted_paper_ids,
    corpusTotal: 551 }) }))
const progress = await renderToString(
  createSSRApp({ render: () => h(PanelProgress, { digest: d }) }))

const EXPECT = [
  ['overview shows the question', overview, 'multi-agent retrieval-augmented'],
  ['overview shows grounding', overview, '86.36%'],
  ['overview shows the decision chain', overview, 'REPLAN'],
  ['overview shows the LLM bill', overview, '10'],
  ['overview names the PARTIAL cap', overview, 'capped at PARTIAL'],
  ['progress shows a critic reason', progress, 'below min_papers'],
  ['progress shows the search rounds', progress, 'papers added'],
  ['progress shows rerank cost', progress, 'Rank'],
  ['sources shows the funnel', sources, 'retrieved'],
  ['sources resolves a DOI', sources, 'doi.org'],
]
for (const [label, html, needle] of EXPECT) {
  const ok = html.includes(needle)
  if (!ok) failures += 1
  console.log(`  ${ok ? 'ok  ' : 'FAIL'} ${label}`)
}

console.log(failures ? `\n${failures} FAILURES` : '\nall render checks passed')
process.exit(failures ? 1 : 0)

