async function probe(width, path) {
  const f = document.createElement('iframe');
  f.style.cssText = `position:fixed;left:-9999px;top:0;width:${width}px;height:900px;border:0`;
  f.src = path;
  document.body.appendChild(f);
  await new Promise(r => { f.onload = r; setTimeout(r, 6000); });
  await new Promise(r => setTimeout(r, 2500));   // let Vue fetch + render
  const d = f.contentDocument, w = f.contentWindow;
  const de = d.documentElement;
  const offenders = [...d.querySelectorAll('body *')]
    .filter(e => {
      const r = e.getBoundingClientRect();
      if (r.right <= de.clientWidth + 2) return false;
      // a container that scrolls its own overflow is doing the right thing
      for (let n = e; n; n = n.parentElement) {
        if (n.scrollWidth > n.clientWidth && ['auto','scroll'].includes(getComputedStyle(n).overflowX)) return false;
      }
      return true;
    })
    .slice(0, 6)
    .map(e => ({ tag: e.tagName, cls: String(e.className.baseVal ?? e.className).slice(0, 70), right: Math.round(e.getBoundingClientRect().right) }));
  const res = { width, path, viewport: de.clientWidth, scrollW: de.scrollWidth,
                overflows: de.scrollWidth > de.clientWidth + 1, offenders,
                panels: d.querySelectorAll('section.panel').length };
  f.remove();
  return res;
}
