      for (let n = e; n; n = n.parentElement)
        if (n.scrollWidth > n.clientWidth && ['auto','scroll'].includes(getComputedStyle(n).overflowX)) return false;
      return true;
    })
    .slice(0, 4)
    .map(e => String(e.className.baseVal ?? e.className).slice(0, 60));
  const res = { path, width, viewport: vw, scrollW: de.scrollWidth,
